# -*- coding: utf-8 -*-
"""Catalogue of the 89 Mũ-Logarit types: name used for routing + a signature that every question of the type matches.

pattern  is a regular expression searched in common.norm(question stem) (no spaces, no dollar signs).
close_to lists the nearest types and the feature that separates them; the audit script prints it.
"""

# pieces reused by several signatures (written on the normalised stem)
LIN = r"\{-?\d*x?(?:[+-]\d+)?\}"          # a linear or constant exponent in braces: {2x+1}, {x-4}, {-1}
POW = r"\d+\^(?:" + LIN + r"|-?\d+)"      # a power whose exponent is linear or constant: 3^{2x+1}, 7^2
ROOT = r"\\sqrt(?:\[\d+\])?\{a\}"          # sqrt{a}, sqrt[3]{a}

